-- q-sol-pharma-pty-ltd-waltloo (researched)
UPDATE businesses SET description = 'Q-SOL Pharma runs a pharmaceutical manufacturing facility on Waltloo Road that has been in operation for more than 50 years, evolving from the original Noristan family business through several ownerships into its current form. Its management team brings a combined 100-plus years of pharmaceutical industry experience to contract manufacturing, packaging and analytical testing services for more than a dozen customers, with capability spanning solid dosage manufacturing, complementary medicines, creams and ointments, and oral liquids such as syrups and suspensions.

Its packaging lines cover liquid filling, aluminium tube filling, blister packs and tablet counting into glass bottles or securitainers, while its analytical testing covers post-importation testing, HPLC and GC analysis, microbiological testing and stability testing across multiple climate zones. The plant is SAHPRA GMP approved and ISO 45001 and ISO 14001 certified, and is a B-BBEE Level 3 contributor, making it a credentialed contract manufacturing partner for pharmaceutical brands that need capacity without building their own facility.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'http://qsolpharma.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'q-sol-pharma-pty-ltd-waltloo' AND description = 'Q-SOL Pharma (Pty) Ltd runs a pharmaceutical manufacturing facility on Waltloo Road that has been operating for more than 50 years, having evolved from the original Noristan family business. The SAHPRA GMP-approved, ISO 45001 and ISO 14001 certified plant provides contract manufacturing, packaging and analytical services to more than a dozen customers.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
