-- wilgers-hospital-die-wilgers (researched)
UPDATE businesses SET description = 'Life Wilgers Hospital, in the leafy suburb of Lynnwood Ridge in Pretoria, is one of the largest hospitals in the Life Healthcare Group with 360 beds split across its various faculties. Its facilities include a 24-hour accident and emergency unit with a helicopter landing pad, a 46-bed intensive care unit and a 16-bed neonatal ICU, backed by specialists from 22 different medical and surgical disciplines able to handle anything from routine procedures to serious, complex cases.

The hospital offers online pre-admission so patients can complete paperwork before arriving, and provides guidance for visitors and families on visiting hours, infection prevention and what to expect during an emergency unit visit. As part of the wider Life Healthcare network, Wilgers Hospital gives patients in Pretoria East access to a broad range of medical and surgical disciplines, from cardiology and neurosurgery to obstetrics and oncology, within a single hospital campus.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.lifehealthcare.co.za/hospitals/gauteng/pretoria/life-wilgers-hospital/?utm_source=google_maps&utm_medium=website_button&utm_campaign=SP&utm_content=SP'), description_enriched_at = datetime('now') WHERE slug = 'wilgers-hospital-die-wilgers' AND description = 'Wilgers Hospital is a 360-bed private hospital in Die Wilgers, Pretoria, one of the largest in the Life Healthcare Group, with an accident and emergency unit and helicopter landing pad, a 46-bed intensive care unit, a 16-bed neonatal ICU and 22 medical and surgical disciplines including cardiology, neurosurgery, orthopaedics, obstetrics and oncology.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
